```python
import json
import requests
import re
import ssl
import urllib.parse

def extract_pages(data):
    """递归提取所有页面内容"""
    pages = []
    if isinstance(data, dict):
        if 'pages' in data:
            for page in data['pages']:
                if isinstance(page, dict):
                    pages.append({
                        'url': page.get('url', ''),
                        'title': page.get('title', ''),
                        'content': page.get('content', ''),
                        'markdown': page.get('markdown', '')
                    })
        for value in data.values():
            pages.extend(extract_pages(value))
    elif isinstance(data, list):
        for item in data:
            pages.extend(extract_pages(item))
    return pages

def main(brand: str, region: str, search_result: str):
    """
    根据品牌和区域搜索冰箱新品
    brand: 品牌名
    region: 区域名
    search_result: 搜索结果JSON字符串
    """
    # 解析搜索结果
    try:
        search_data = json.loads(search_result) if isinstance(search_result, str) else search_result
    except:
        search_data = {"results": []}

    # 提取所有页面内容
    pages = extract_pages(search_data)

    # 过滤冰箱相关页面
    fridge_pages = []
    fridge_keywords = ['refrigerator', 'fridge', '冰箱', 'freezer', 'cooling']

    for page in pages:
        content = (page.get('content', '') + ' ' + page.get('markdown', '')).lower()
        url = page.get('url', '').lower()

        is_fridge = any(kw in content or kw in url for kw in fridge_keywords)

        if is_fridge:
            fridge_pages.append({
                'url': page.get('url', ''),
                'title': page.get('title', ''),
                'content': page.get('markdown', page.get('content', ''))[:2000]
            })

    # 提取型号信息
    models = []
    model_patterns = [
        r'[A-Z]{2,4}[-\s]?\d{2,4}[A-Z]*',
        r'[A-Z]{1,2}\d{2}[A-Z]\d{2}[A-Z]{2}',
    ]

    for page in fridge_pages:
        for pattern in model_patterns:
            found = re.findall(pattern, page.get('content', ''))
            for m in found:
                if len(m) >= 5 and m not in [x['model'] for x in models]:
                    models.append({
                        'model': m,
                        'source_url': page.get('url', ''),
                        'source_title': page.get('title', '')
                    })

    return {
        'brand': brand,
        'region': region,
        'pages_found': len(fridge_pages),
        'models_found': models,
        'pages': fridge_pages[:5]
    }
